 int iVersion; /* Currently always 2 */

int (*xCreate)(void*, const char **azArg, int nArg, Fts5Tokenizer **ppOut);
 void (*xDelete)(Fts5Tokenizer*);
 int (*xTokenize)(Fts5Tokenizer*, 
 void *pCtx,
