 }
 } while( rc==SQLITE_OK || rc==SQLITE_BUSY || rc==SQLITE_LOCKED );

/* Release resources allocated by backup_init(). */
 (void)sqlite3_backup_finish(pBackup);
 }
 rc = sqlite3_errcode(pFile);
