If you have a type object defined with "PyType_FromModuleAndSpec()",
you can call "PyType_GetModule()" to get the associated module, and
then "PyModule_GetState()" to get the module's state.

static int
 spam_module_exec(PyObject *m)
 {
 if (SpamError != NULL) {
 PyErr_SetString(PyExc_ImportError,
 "cannot initialize spam module more than once");
 return -1;
 }
 SpamError = PyErr_NewException("spam.error", NULL, NULL);
 if (PyModule_AddObjectRef(m, "SpamError", SpamError) < 0) {
 return -1;
 }

static PyModuleDef_Slot spam_module_slots[] = {
 {Py_mod_exec, spam_module_exec},
 {0, NULL}
 };

static struct PyModuleDef spam_module = {
 .m_base = PyModuleDef_HEAD_INIT,
 .m_name = "spam",
 .m_size = 0, // non-negative
 .m_slots = spam_module_slots,
 };

Note that the Python name for the exception object is "spam.error".
The "PyErr_NewException()" function may create a class with the base
class being "Exception" (unless another class is passed in instead of
"NULL"), described in Built-in Exceptions.

Note also that the "SpamError" variable retains a reference to the
newly created exception class; this is intentional! Since the
exception could be removed from the module by external code, an owned
reference to the class is needed to ensure that it will not be
discarded, causing "SpamError" to become a dangling pointer. Should it
become a dangling pointer, C code which raises the exception could
cause a core dump or other unintended side effects.

/*
** Argument zSql points to a buffer containing an SQL script to execute
** against the database handle passed as the first argument. As well as
** executing the SQL script, this function collects a changeset recording
** all changes made to the "main" database file. Assuming no error occurs,
** output variables (*ppChangeset) and (*pnChangeset) are set to point
** to a buffer containing the changeset and the size of the changeset in
** bytes before returning SQLITE_OK. In this case it is the responsibility
** of the caller to eventually free the changeset blob by passing it to
** the sqlite3_free function.
**
** Or, if an error does occur, return an SQLite error code. The final
** value of (*pChangeset) and (*pnChangeset) are undefined in this case.
*/
int sql_exec_changeset(
 sqlite3 *db, /* Database handle */
 const char *zSql, /* SQL script to execute */
 int *pnChangeset, /* OUT: Size of changeset blob in bytes */
 void **ppChangeset /* OUT: Pointer to changeset blob */
){
 sqlite3_session *pSession = 0;
 int rc;

/* Create a new session object */
 rc = sqlite3session_create(db, "main", &pSession);

/* Configure the session object to record changes to all tables */
 if( rc==SQLITE_OK ) rc = sqlite3session_attach(pSession, NULL);

/* Execute the SQL script */
 if( rc==SQLITE_OK ) rc = sqlite3_exec(db, zSql, 0, 0, 0);

