/*
** Print the contents of the changeset to stdout.
*/
static int print_changeset(void *pChangeset, int nChangeset){
 int rc;
 sqlite3_changeset_iter *pIter = 0;

/* Create an iterator to iterate through the changeset */
 rc = sqlite3changeset_start(&pIter, nChangeset, pChangeset);
 if( rc!=SQLITE_OK ) return rc;

/* This loop runs once for each change in the changeset */
 while( SQLITE_ROW==sqlite3changeset_next(pIter) ){
 const char *zTab; /* Table change applies to */
 int nCol; /* Number of columns in table zTab */
 int op; /* SQLITE_INSERT, UPDATE or DELETE */
 sqlite3_value *pVal;

/* Print the type of operation and the table it is on */
 rc = sqlite3changeset_op(pIter, &zTab, &nCol, &op, 0);
 if( rc!=SQLITE_OK ) goto exit_print_changeset;
 printf("%s on table %s\n",
 op==SQLITE_INSERT?"INSERT" : op==SQLITE_UPDATE?"UPDATE" : "DELETE",
 zTab
 );

/* If this is an UPDATE or DELETE, print the old.* values */
 if( op==SQLITE_UPDATE || op==SQLITE_DELETE ){
 printf("Old values:");
 for(i=0; i<nCol; i++){
 rc = sqlite3changeset_old(pIter, i, &pVal);
 if( rc!=SQLITE_OK ) goto exit_print_changeset;
 printf(" %s", pVal ? sqlite3_value_text(pVal) : "-");
 }
 printf("\n");
 }

/*
** This function assumes that an SQLite API call (either sqlite3_prepare_v2() 
** or sqlite3_step()) has just returned SQLITE_LOCKED. The argument is the
** associated database connection.
**
** This function calls sqlite3_unlock_notify() to register for an 
** unlock-notify callback, then blocks until that callback is delivered 
** and returns SQLITE_OK. The caller should then retry the failed operation.
**
** Or, if sqlite3_unlock_notify() indicates that to block would deadlock 
** the system, then this function returns SQLITE_LOCKED immediately. In 
** this case the caller should not retry the operation and should roll 
** back the current transaction (if any).
*/
static int wait_for_unlock_notify(sqlite3 *db){
 int rc;
 UnlockNotification un;

/* Initialize the UnlockNotification structure. */
 un.fired = 0;
 pthread_mutex_init(&un.mutex, 0);
 pthread_cond_init(&un.cond, 0);

/* Register for an unlock-notify callback. */
 rc = sqlite3_unlock_notify(db, unlock_notify_cb, (void *)&un);
 assert( rc==SQLITE_LOCKED || rc==SQLITE_OK );

If the returned value is greater than *n_bytes*, the value was
 truncated: as many of the lowest bits of the value as could fit are
 written, and the higher bits are ignored. This matches the typical
 behavior of a C-style downcast.

Overflow is not considered an error. If the returned value is
 larger than *n_bytes*, most significant bits were discarded.

int32_t value;
 Py_ssize_t bytes = PyLong_AsNativeBytes(pylong, &value, sizeof(value), -1);
 if (bytes < 0) {
 // Failed. A Python exception was set with the reason.
 return NULL;
 }
 else if (bytes <= (Py_ssize_t)sizeof(value)) {
 // Success!
 }
 else {
 // Overflow occurred, but 'value' contains the truncated
 // lowest bits of pylong.
 }

Passing zero to *n_bytes* will return the size of a buffer that
 would be large enough to hold the value. This may be larger than
 technically necessary, but not unreasonably so. If *n_bytes=0*,
 *buffer* may be "NULL".

Passing *n_bytes=0* to this function is not an accurate way to
 determine the bit length of the value.

To get at the entire Python value of an unknown size, the function
 can be called twice: first to determine the buffer size, then to
 fill it:

